import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第八百五十一章 什么是神足？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/851第八百五十一章 什么是神足-四神足.md","filePath":"meditation/巴利文大藏经/851第八百五十一章 什么是神足-四神足.md"}'),o={name:"meditation/巴利文大藏经/851第八百五十一章 什么是神足-四神足.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第八百五十一章-什么是神足" tabindex="-1">第八百五十一章 什么是神足？ <a class="header-anchor" href="#第八百五十一章-什么是神足" aria-label="Permalink to &quot;第八百五十一章 什么是神足？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>51.(7)神足相应</p><p>1.价玻勒品</p><p>相应部51相应1经/此岸经(神足相应/大篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），有四种神足，当众生经常修习这四种神足的时候，这四种神足就能指引、引导众生从充满烦恼和痛苦的此岸到达没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的解脱彼岸（众生解释，见第三百八十八章）。是哪四种神足呢？即是欲三摩地断行成就神足、心三摩地断行成就神足、勤三摩地断行成就神足、观三摩地断行成就神足，这四种神足。</p><p>什么是欲三摩地断行成就神足呢？就是由想进入各种清净境界，想证悟各种解脱果位的欲望而精进努力的修行进入清净安宁境界的修行方法，比如想要从生死轮回中永远的解脱出来，证悟阿罗汉果位，就精进的去修行，从而达到没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃清净境界，证悟阿罗汉果位。由这种想要永远从生死轮回中解脱出来，证悟阿罗汉果位的欲望而进入涅槃清净的境界。简单的说就是由各种想要进入清净境界，想要证悟各种解脱果位的欲望而努力修行达到清净安宁境界的修行方法就是欲三摩地断行成就神足。</p><p>什么是心三摩地断行成就神足呢？就是由控制内心的念想，让念想单一、纯正，或者由熄灭内心的念想，不让内心的念想生起而精进努力的修行进入清净安宁境界的修行方法，比如当内心想到各种让自己烦恼和痛苦的事情的时候，就将注意力集中专注在一片树叶上，除了观察树叶的念想外不再想其他的事情，这样内心就只有一个观察树叶的念想了，念想就变的单个、纯一了，由烦恼和痛苦生起的念想就被观察树叶的念想替换掉了，烦恼和痛苦也就熄灭、平息、灭尽了。</p><p>或者当内心想到各种令人烦恼痛苦的事情的时候。就将自己的注意力集中专注在数呼吸的念想上，数吸气的次数，或者数呼气的次数，比丘们，这里要注意，不是同时数吸气和呼气的次数，而是在吸气和呼气这两者中选择其中一种计数，或者数吸气的次数，或者数呼气的次数。这样去修行就能用集中专注数吸气次数的念想，或用集中专注数呼气次数的念想替换掉烦恼痛苦的念想。</p><p>又比如内心想到了自己喜欢的黄金、钱财、美女，这个时候就立刻不再去想黄金、钱财、美女，不再内心中生起黄金、钱财、美女的念想，不想的时间一长，自然就进入清净安宁的境界。简单的说就是：控制念想，让念想单一、纯正，或者熄灭念想，不生起念想而达到清净安宁境界的修行方法就是心三摩地断行成就神足。</p><p>什么是勤三摩地断行成就神足呢？就是由持续除灭恶行、恶言、恶念的行为，精进努力去生起善行、善言、善念的行为而进入清净安宁境界的修行方法，比如有个人说谎话欺骗别人，他意识到这样做是错误的，于是他就开诚布公的向别人说明实情，恳请别人原谅他，这个人以后也不再说假话欺骗别人，他由于断恶修善的缘故让自己的内心坦坦荡荡、光明磊落而进入清净安宁的境界。简单的说就是：持续的断恶修善而达到清净安宁境界的修行方法就是勤三摩地断行成就神足。</p><p>什么是观三摩地断行成就神足呢？由经常观想、忆念如来所说正法的法义而进入清净安宁境界的修行方法，比如有一个修行人，他经常的观想世间一切的事物随时在变化，无法永远的存在，无法永恒的保持不变，无法永远的拥有，他由此不再执着和挂念世间一切的事物，进入清净安宁的境界。简单的说就是：通过经常观想、忆念如来的正法而达到清净安宁境界的修行方法就是观三摩地断行成就神足。</p><p>比丘们！这就是四神足的法义。</p><p>比丘们，当众生持之以恒、坚持不懈的修习欲三摩地断行成就神足、心三摩地断行成就神足、勤三摩地断行成就神足、观三摩地断行成就神足，这四种神足的时候，他们就能从烦恼痛苦的此岸到达清净解脱的彼岸。比丘们，你们要注意，不是同时修习四种神足，而是在欲三摩地断行成就神足、心三摩地断行成就神足、勤三摩地断行成就神足、观三摩地断行成就神足，这四种神足中选择其中一种神足修习，或者修习欲三摩地断行成就神足，或者修习心三摩地断行成就神足，或者修习勤三摩地断行成就神足，或者修习观三摩地断行成就神足。选择经常修习四种神足中的任意一种神足，都能最终被指引、引导进入没有烦恼，没有痛苦，没有执着，没有挂念，没有念想的涅槃彼岸。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',15)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
